"""Tests for data model validation utility."""

import pytest

from warp_simdata.data_models.validation import validate_all_builtin_models, validate_data_model


@pytest.mark.datamodel
@pytest.mark.vtk
def test_vtk_image_data_validation():
    """Test that VTK image data model passes validation."""
    from warp_simdata.data_models.vtk import image_data

    is_valid, errors = validate_data_model(image_data.DataModel, verbose=False)
    assert is_valid, f"VTK image data model should be valid. Errors: {errors}"


