@pytest.mark.datamodel
@pytest.mark.vtk
@pytest.mark.collection
def test_collection_validation():
    """Test that collection data models pass validation for all base models."""
    from warp_simdata.data_models import collection
    from warp_simdata.data_models.vtk import image_data, structured_grid

    base_models = {"image_data": image_data.DataModel, "structured_grid": structured_grid.DataModel}

    for name, base_model in base_models.items():
        collection_model = collection.get_collection_data_model(base_model)
        is_valid, errors = validate_data_model(collection_model, verbose=False)
        assert is_valid, f"Collection({name}) model should be valid. Errors: {errors}"


