@pytest.mark.datamodel
def test_all_builtin_models_validation():
    """Test that all built-in data models pass validation."""
    results = validate_all_builtin_models(verbose=False)

    # Check that we got results for all expected models
    expected_models = ["vtk.image_data", "vtk.structured_grid", "vtk.unstructured_grid", "sids.unstructured", "reservoir.corner_point_grid", "collection"]

    for model_name in expected_models:
        assert model_name in results, f"Missing validation result for {model_name}"

    # Check that all models are valid
    invalid_models = []
    for model_name, (is_valid, errors) in results.items():
        if not is_valid:
            invalid_models.append((model_name, errors))

    assert len(invalid_models) == 0, f"Some data models are invalid: {[(name, errs) for name, errs in invalid_models]}"

