"""A partial data model: python docs/examples/custom_model.py --device cpu.

Disconnected segments store their starts and ends in separate arrays. Element
and node IDs are one-based; logical node indices interleave each start and end.
Only bounds, centroid, element_sizes, and element_field are supported here.
Faces, contouring, spatial queries, interpolation, reverse links, collections,
and AOT reconstruction are outside this example's scope. It intentionally does
not implement the full DataModel protocol or pass validate_data_model().
"""

import argparse

import numpy as np
import warp as wp

import warp_simdata as simdata
from warp_simdata.operators import bounds, centroid, element_field, element_sizes


@wp.struct
class DatasetHandle:
    starts: wp.array(dtype=wp.vec3f)
    ends: wp.array(dtype=wp.vec3f)


@wp.struct
class NodeCursor:
    elem_idx: wp.int32
    count: wp.int32


class ElementAPI:
    @staticmethod
    @simdata.func
    def empty() -> wp.int32:
        return 0

    @staticmethod
    @simdata.func
    def is_valid(elem: wp.int32) -> wp.bool:
        return elem > 0

    @staticmethod
    @simdata.func
    def get_elem_id(elem: wp.int32) -> wp.int32:
        return elem

    @staticmethod
    @simdata.func
    def get_nodes(ds: DatasetHandle, elem: wp.int32) -> NodeCursor:
        nodes = NodeCursor()
        nodes.elem_idx = elem - 1
        nodes.count = 2 if elem > 0 else 0
        return nodes

    @staticmethod
    @simdata.func
    def get_num_nodes(nodes: NodeCursor) -> wp.int32:
        return nodes.count

    @staticmethod
    @simdata.func
    def get_node_id(ds: DatasetHandle, nodes: NodeCursor, local_idx: wp.int32) -> wp.int32:
        return 2 * nodes.elem_idx + local_idx + 1


class DatasetAPI:
    @staticmethod
    @simdata.func
    def get_num_elems(ds: DatasetHandle) -> wp.int32:
        return ds.starts.shape[0]

    @staticmethod
    @simdata.func
    def get_num_nodes(ds: DatasetHandle) -> wp.int32:
        return 2 * ds.starts.shape[0]

    @staticmethod
    @simdata.func
    def get_node_id_from_idx(ds: DatasetHandle, node_idx: wp.int32) -> wp.int32:
        return node_idx + 1

    @staticmethod
    @simdata.func
    def get_node_idx_from_id(ds: DatasetHandle, node_id: wp.int32) -> wp.int32:
        return node_id - 1

    @staticmethod
    @simdata.func
    def get_node_coords(ds: DatasetHandle, node_id: wp.int32) -> wp.vec3f:
        node_idx = node_id - 1
        elem_idx = node_idx // 2
        if node_idx % 2 == 0:
            return ds.starts[elem_idx]
        return ds.ends[elem_idx]

    @staticmethod
    @simdata.func
    def get_elem_id_from_idx(ds: DatasetHandle, elem_idx: wp.int32) -> wp.int32:
        return elem_idx + 1

    @staticmethod
    @simdata.func
    def get_elem_idx_from_id(ds: DatasetHandle, elem_id: wp.int32) -> wp.int32:
        return elem_id - 1

    @staticmethod
    @simdata.func
    def get_elem_from_id(ds: DatasetHandle, elem_id: wp.int32) -> wp.int32:
        if elem_id > 0 and elem_id <= ds.starts.shape[0]:
            return elem_id
        return ElementAPI.empty()

    @staticmethod
    @simdata.func
    def get_elem_from_idx(ds: DatasetHandle, elem_idx: wp.int32) -> wp.int32:
        return DatasetAPI.get_elem_from_id(ds, elem_idx + 1)

    @staticmethod
    def build_element_locator(data_model, handle, device):
        raise NotImplementedError("This segment example does not support spatial queries.")

    @staticmethod
    def build_node_element_links(data_model, handle, device):
        raise NotImplementedError("This segment example does not support node-to-element links.")


class DataModel:
    DatasetHandle = DatasetHandle
    ElementHandle = wp.int32
    NodeIdHandle = wp.int32
    ElementIdHandle = wp.int32
    DatasetAPI = DatasetAPI
    ElementAPI = ElementAPI


def create_dataset(starts: wp.array, ends: wp.array) -> simdata.Dataset:
    """Wrap nonempty, equal-length vec3f endpoint arrays on one device without copying."""
    for name, array in (("starts", starts), ("ends", ends)):
        if array.ndim != 1 or array.dtype != wp.vec3f:
            raise ValueError(f"{name} must be a one-dimensional wp.vec3f array")
    if starts.size == 0 or starts.size != ends.size:
        raise ValueError("starts and ends must have the same nonzero length")
    if starts.device != ends.device:
        raise ValueError("starts and ends must be on the same device")
    handle = DatasetHandle()
    handle.starts = starts
    handle.ends = ends
    return simdata.Dataset(DataModel, handle, starts.device.alias)


def main(device: str):
    device = wp.get_device(device).alias
    starts = wp.array([[0.0, 0.0, 0.0], [0.0, 2.0, 0.0]], dtype=wp.vec3f, device=device)
    ends = wp.array([[2.0, 0.0, 0.0], [0.0, 2.0, 4.0]], dtype=wp.vec3f, device=device)
    dataset = create_dataset(starts, ends)
    assert dataset.get_num_elems() == 2 and dataset.get_num_nodes() == 4
    assert not ElementAPI.is_valid(DatasetAPI.get_elem_from_idx(dataset.handle, -1))
    assert not ElementAPI.is_valid(DatasetAPI.get_elem_from_idx(dataset.handle, 2))

    # Logical field order: start 0, end 0, start 1, end 1.
    values = wp.array([0.0, 2.0, 2.0, 6.0], dtype=wp.float32, device=device)
    dataset.add_field("values", simdata.Field.from_array(values, simdata.AssociationType.NODE))

    result = bounds.compute(dataset)
    result = centroid.compute(result)
    result = element_sizes.compute(result)
    result = element_field.compute(result, "values", output_field_name="averages")
    np.testing.assert_allclose(result.get_field("bounds_min").to_array().numpy(), [[0.0, 0.0, 0.0]])
    np.testing.assert_allclose(result.get_field("bounds_max").to_array().numpy(), [[2.0, 2.0, 4.0]])
    np.testing.assert_allclose(result.get_field("element_centers").to_array().numpy(), [[1.0, 0.0, 0.0], [0.0, 2.0, 2.0]])
    np.testing.assert_allclose(result.get_field("element_sizes").to_array().numpy(), [2.0, 4.0])
    np.testing.assert_allclose(result.get_field("averages").to_array().numpy(), [1.0, 4.0])
    assert not dataset.has_field("averages")
    print(f"Custom model example passed on {device}: centers=[[1, 0, 0], [0, 2, 2]], averages=[1, 4]")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--device", default="cpu", help="Warp device, for example cpu or cuda:0 (default: cpu)")
    main(parser.parse_args().device)
